/**
 * The adapter's half of the detailed city look (the `detailedCity` map
 * feature): the material's data, and the 3D-mode ground.
 *
 * Imported only by `city3dLayer.web.ts`, which is itself lazy, so none of it
 * reaches the first-paint bundle. It must not import the engine folder at
 * runtime (see `components/__tests__/engine3dChunk.test.ts`): the material
 * values travel to the engine as plain data.
 *
 * ## The ground
 *
 * The overrides are generated by the style pipeline into the loaded style's
 * own `metadata` (`lib/map/style/city3dGround.ts`), so this applies whatever
 * the document carries and names no layer or colour itself. A style without
 * them — `openfreemap`, an override URL — keeps its ground. Every property is
 * restored on detach to exactly what it was.
 */
import {
  CITY_MATERIALS,
  CITY3D_GROUND_METADATA_KEY,
  type CityMaterial,
  type GroundOverride,
} from '@/lib/map/style/palette3d';

/**
 * The detailed material's day and night, as plain data for the engine. How
 * much of each is drawn is the engine's night seam (`setNightFactor`, fed by
 * `lib/map/landmarks/night.ts` or the city sky's time of day), blended on the
 * GPU — this file keeps no night factor of its own.
 */
export function cityMaterials(): { day: CityMaterial; night: CityMaterial } {
  return CITY_MATERIALS;
}

/** The slice of MapLibre's `Map` the ground needs (so the tests can fake it). */
export interface GroundHost {
  getStyle(): { metadata?: unknown } | undefined;
  getLayer(id: string): unknown;
  getPaintProperty(layer: string, property: string): unknown;
  setPaintProperty(layer: string, property: string, value: unknown): void;
}

/** The overrides the loaded style carries, or `[]` (none, or not the expected shape). */
export function groundOverridesOf(host: GroundHost): GroundOverride[] {
  const metadata = host.getStyle()?.metadata as Record<string, unknown> | undefined;
  const raw = metadata?.[CITY3D_GROUND_METADATA_KEY];
  if (!Array.isArray(raw)) return [];
  return raw.filter(
    (o): o is GroundOverride =>
      typeof o === 'object' &&
      o !== null &&
      typeof (o as GroundOverride).layer === 'string' &&
      typeof (o as GroundOverride).property === 'string' &&
      'value' in o,
  );
}

/**
 * Switch the basemap to the 3D city's ground. Returns the undo, which puts
 * back every property it changed (and tolerates a map already torn down).
 */
export function applyCityGround(host: GroundHost): () => void {
  const previous: { layer: string; property: string; value: unknown }[] = [];
  for (const override of groundOverridesOf(host)) {
    if (!host.getLayer(override.layer)) continue;
    previous.push({
      layer: override.layer,
      property: override.property,
      value: host.getPaintProperty(override.layer, override.property),
    });
    host.setPaintProperty(override.layer, override.property, override.value);
  }
  return () => {
    for (const { layer, property, value } of previous.reverse()) {
      try {
        if (host.getLayer(layer)) host.setPaintProperty(layer, property, value);
      } catch {
        // A removed map throws on style access; its ground went with it.
      }
    }
  };
}
